using Microsoft.EntityFrameworkCore;

public sealed class SignUp(ShopDb db)
{
    // NormalizedEmail is set on save and has a unique index
    public Task<bool> EmailTakenAsync(string email, CancellationToken ct)
    {
        var normalized = email.Trim().ToUpperInvariant();
        return db.Customers.AnyAsync(c => c.NormalizedEmail == normalized, ct);
