using Microsoft.EntityFrameworkCore;
using Shop;
using Xunit;

public sealed class SignUpTests(SqlServerFixture fixture)
    : IClassFixture<SqlServerFixture>
{
    [Fact]
    public async Task Finds_an_email_in_any_case()
    {
        // Real SQL Server: a container in CI, LocalDB on a dev machine
        await using var db = fixture.CreateContext();
        // Never committed, so it's rolled back when the context is disposed
        await db.Database.BeginTransactionAsync();
        db.Customers.Add(new Customer
            { Email = "Ana@Example.com", NormalizedEmail = "ANA@EXAMPLE.COM" });
        await db.SaveChangesAsync();
        db.ChangeTracker.Clear();

        var taken = await new SignUp(db)
            .EmailTakenAsync("ana@example.com", default);
        Assert.True(taken);
    }
}
